content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Courier New', Courier, monospace;
}

body {
  background-color: #121212;
  color: #00ff66;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
  touch-action: manipulation;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 400px;
  padding: 16px;
  background-color: #1e1e1e;
  border: 4px solid #00ff66;
  border-radius: 12px;
  box-shadow: 0 0 20px rgba(0, 255, 102, 0.4);
}

.game-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  margin-bottom: 12px;
}

.game-header h1 {
  font-size: 24px;
  letter-spacing: 2px;
  margin-bottom: 8px;
  text-shadow: 0 0 8px rgba(0, 255, 102, 0.6);
}

.score-board {
  display: flex;
  justify-content: space-between;
  width: 100%;
  font-size: 14px;
  padding: 6px 12px;
  background-color: #2a2a2a;
  border: 2px solid #00ff66;
  border-radius: 6px;
}

.game-board {
  display: grid;
  background-color: #0a0a0a;
  border: 3px solid #00ff66;
  border-radius: 4px;
  width: 300px;
  height: 300px;
  position: relative;
  margin-bottom: 16px;
}

.cell {
  width: 100%;
  height: 100%;
}

.snake {
  background-color: #00ff66;
  border-radius: 2px;
  box-shadow: inset 0 0 4px rgba(0, 0, 0, 0.5);
}

.food {
  background-color: #ff3333;
  border-radius: 50%;
  box-shadow: 0 0 6px #ff3333;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(0.85); }
  100% { transform: scale(1.1); }
}

.controls-container {
  display: flex;
  justify-content: center;
  width: 100%;
  margin-top: 8px;
}

.d-pad {
  display: grid;
  grid-template-columns: repeat(3, 60px);
  grid-template-rows: repeat(2, 60px);
  gap: 8px;
  justify-items: center;
  align-items: center;
}

.d-btn {
  background-color: #2a2a2a;
  color: #00ff66;
  border: 2px solid #00ff66;
  border-radius: 8px;
  font-size: 20px;
  font-weight: bold;
  width: 60px;
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  box-shadow: 0 4px 0 #005522;
  transition: transform 0.1s, box-shadow 0.1s, background-color 0.1s;
}

.d-btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #005522;
  background-color: #00ff66;
  color: #121212;
}

/* 十字キーの配置調整 */
.d-btn:nth-child(1) { /* 上 */
  grid-column: 2;
  grid-row: 1;
}

.d-btn:nth-child(2) { /* 左 */
  grid-column: 1;
  grid-row: 2;
}

.d-btn:nth-child(3) { /* 右 */
  grid-column: 3;
  grid-row: 2;
}

.d-btn:nth-child(4) { /* 下 */
  grid-column: 2;
  grid-row: 2;
}

.btn {
  background-color: #00ff66;
  color: #121212;
  border: none;
  border-radius: 6px;
  padding: 10px 20px;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  box-shadow: 0 4px 0 #005522;
  transition: transform 0.1s, box-shadow 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.btn:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #005522;
}

.game-over-modal {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(18, 18, 18, 0.85);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border-radius: 4px;
  z-index: 10;
  animation: fadeIn 0.3s ease-in-out;
}

.game-over-modal h2 {
  color: #ff3333;
  font-size: 28px;
  margin-bottom: 12px;
  text-shadow: 0 0 10px rgba(255, 51, 51, 0.6);
}

.game-over-modal p {
  font-size: 16px;
  margin-bottom: 20px;
  color: #ffffff;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

export interface Point {
  x: number;
  y: number;
}

export interface Direction {
  x: number;
  y: number;
}

export interface GameState {
  score: number;
  highScore: number;
  isPlaying: boolean;
  isGameOver: boolean;
  isPaused: boolean;
}

import { Point } from './types';

interface SnakeBoardProps {
  snake: Point[];
  food: Point;
  boardSize: number;
}

export default function SnakeBoard({ snake, food, boardSize }: SnakeBoardProps) {
  const cells = [];
  for (let y = 0; y < boardSize; y++) {
    for (let x = 0; x < boardSize; x++) {
      const isSnake = snake.some((segment) => segment.x === x && segment.y === y);
      const isFood = food.x === x && food.y === y;

      let className = 'cell';
      if (isSnake) className += ' snake';
      if (isFood) className += ' food';

      cells.push(<div key={`${x}-${y}`} className={className} />);
    }
  }

  return (
    <div
      className="game-board"
      style={{
        display: 'grid',
        gridTemplateColumns: `repeat(${boardSize}, 1fr)`,
        gridTemplateRows: `repeat(${boardSize}, 1fr)`,
      }}
    >
      {cells}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Point, Direction, GameState } from './types';
import SnakeBoard from './SnakeBoard';

const BOARD_SIZE = 15;
const INITIAL_SPEED = 150;
const INITIAL_SNAKE: Point[] = [
  { x: 7, y: 7 },
  { x: 6, y: 7 },
  { x: 5, y: 7 },
];
const INITIAL_DIRECTION: Direction = { x: 1, y: 0 };
const INITIAL_FOOD: Point = { x: 10, y: 7 };

export default function App() {
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [direction, setDirection] = useState<Direction>(INITIAL_DIRECTION);
  const [nextDirection, setNextDirection] = useState<Direction>(INITIAL_DIRECTION);
  const [food, setFood] = useState<Point>(INITIAL_FOOD);

  const [gameState, setGameState] = useState<GameState>({
    score: 0,
    highScore: 0,
    isPlaying: false,
    isGameOver: false,
    isPaused: false,
  });

  useEffect(() => {
    const savedHighScore = localStorage.getItem('snake_high_score');
    if (savedHighScore) {
      setGameState((prev) => ({ ...prev, highScore: parseInt(savedHighScore, 10) }));
    }
  }, []);

  const generateFood = useCallback((currentSnake: Point[]): Point => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * BOARD_SIZE),
        y: Math.floor(Math.random() * BOARD_SIZE),
      };
      const isOnSnake = currentSnake.some((seg) => seg.x === newFood.x && seg.y === newFood.y);
      if (!isOnSnake) break;
    }
    return newFood;
  }, []);

  const startGame = () => {
    const newSnake = INITIAL_SNAKE;
    setSnake(newSnake);
    setDirection(INITIAL_DIRECTION);
    setNextDirection(INITIAL_DIRECTION);
    setFood(generateFood(newSnake));
    setGameState((prev) => ({
      ...prev,
      score: 0,
      isPlaying: true,
      isGameOver: false,
      isPaused: false,
    }));
  };

  const changeDirection = useCallback(
    (newDir: Direction) => {
      if (newDir.x !== -direction.x || newDir.y !== -direction.y) {
        setNextDirection(newDir);
      }
    },
    [direction]
  );

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!gameState.isPlaying || gameState.isGameOver) {
        if (e.key === 'Enter' || e.key === ' ') {
          startGame();
        }
        return;
      }

      switch (e.key) {
        case 'ArrowUp':
        case 'w':
        case 'W':
          changeDirection({ x: 0, y: -1 });
          break;
        case 'ArrowDown':
        case 's':
        case 'S':
          changeDirection({ x: 0, y: 1 });
          break;
        case 'ArrowLeft':
        case 'a':
        case 'A':
          changeDirection({ x: -1, y: 0 });
          break;
        case 'ArrowRight':
        case 'd':
        case 'D':
          changeDirection({ x: 1, y: 0 });
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState.isPlaying, gameState.isGameOver, changeDirection]);

  useEffect(() => {
    if (!gameState.isPlaying || gameState.isGameOver || gameState.isPaused) return;

    const timer = setInterval(() => {
      setDirection(nextDirection);

      setSnake((prevSnake) => {
        const head = prevSnake[0];
        const newHead: Point = {
          x: head.x + nextDirection.x,
          y: head.y + nextDirection.y,
        };

        if (
          newHead.x < 0 ||
          newHead.x >= BOARD_SIZE ||
          newHead.y < 0 ||
          newHead.y >= BOARD_SIZE
        ) {
          setGameState((prev) => ({ ...prev, isPlaying: false, isGameOver: true }));
          return prevSnake;
        }

        for (let i = 0; i < prevSnake.length; i++) {
          if (prevSnake[i].x === newHead.x && prevSnake[i].y === newHead.y) {
            setGameState((prev) => ({ ...prev, isPlaying: false, isGameOver: true }));
            return prevSnake;
          }
        }

        const newSnake = [newHead, ...prevSnake];

        if (newHead.x === food.x && newHead.y === food.y) {
          const newScore = gameState.score + 10;
          setGameState((prev) => {
            const newHighScore = Math.max(newScore, prev.highScore);
            localStorage.setItem('snake_high_score', newHighScore.toString());
            return {
              ...prev,
              score: newScore,
              highScore: newHighScore,
            };
          });
          setFood(generateFood(newSnake));
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    }, INITIAL_SPEED);

    return () => clearInterval(timer);
  }, [gameState.isPlaying, gameState.isGameOver, gameState.isPaused, nextDirection, food, gameState.score, generateFood]);

  return (
    <div className="app-container">
      <div className="game-header">
        <h1>SNAKE GAME</h1>
        <div className="score-board">
          <span>スコア: {gameState.score}</span>
          <span>ハイスコア: {gameState.highScore}</span>
        </div>
      </div>

      <div style={{ position: 'relative' }}>
        <SnakeBoard snake={snake} food={food} boardSize={BOARD_SIZE} />

        {!gameState.isPlaying && !gameState.isGameOver && (
          <div className="game-over-modal">
            <h2>レトロスネーク</h2>
            <p>方向キーまたはボタンで操作</p>
            <button className="btn" onClick={startGame}>ゲームスタート</button>
          </div>
        )}

        {gameState.isGameOver && (
          <div className="game-over-modal">
            <h2>GAME OVER</h2>
            <p>スコア: {gameState.score}</p>
            <button className="btn" onClick={startGame}>やり直す</button>
          </div>
        )}
      </div>

      <div className="controls-container">
        <div className="d-pad">
          <button className="d-btn" onClick={() => changeDirection({ x: 0, y: -1 })}>▲</button>
          <button className="d-btn" onClick={() => changeDirection({ x: -1, y: 0 })}>◀</button>
          <button className="d-btn" onClick={() => changeDirection({ x: 1, y: 0 })}>▶</button>
          <button className="d-btn" onClick={() => changeDirection({ x: 0, y: 1 })}>▼</button>
        </div>
      </div>
    </div>
  );
}
